 "sources": [],
 "ref_check": [
   {"ref": "POK:125", "status": "supports", "note": "POK_01.txt leaf 135, entry beginning at printed p.125 and running onto 126: 'bbelgh- schwellen; Balg (aufgeblasene Tierhaut), Kissen, Polster (Erw. von bhel- aufblasen usw.). Ai. barhiš n. Streu, Opferstreu = av. barəzis- n. Polster, Kissen, npers. bālis Kissen; ai. upa-barhana-m ... Decke, Polster'. Exactly Nourai's arrow for barəziš-; the page does not mention barəšnu-."}
 ],
